const tokenize = (name: string): string[] => name.split(/[・（）\(\)・との\s]/).filter(Boolean);

const buildKeywords = (name: string): string[] => {
  const tokens = tokenize(name);
  const expanded = tokens.flatMap((token) => TOKEN_ALIASES[token] || [token]);
  return Array.from(new Set([name, ...tokens, ...expanded]));
};

const normalize = (text: string): string => text.replace(/\s+/g, '').toLowerCase();

const isRelated = (problem: GeneralProblem, keywords: string[]): boolean => {
  const haystack = normalize(`${problem.question} ${problem.answer} ${problem.hint || ''}`);
  return keywords.some((keyword) => haystack.includes(normalize(keyword)));
};

const dedupeByQuestion = (problems: GeneralProblem[]): GeneralProblem[] => {
  const seen = new Set<string>();
  return problems.filter((problem) => {
    const key = normalize(problem.question);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const getAssignedSourceSlice = (mode: string, sourceMode: string): GeneralProblem[] => {
  const source = SOURCE_MODE_DATA[sourceMode] || [];
  const group = SOURCE_MODE_UNIT_GROUPS[sourceMode] || [];
  const index = group.indexOf(mode);
  if (index === -1 || group.length === 0) return source;
  const start = Math.floor((source.length * index) / group.length);
  const end = Math.floor((source.length * (index + 1)) / group.length);
  return source.slice(start, end);
};

const expandUnitProblems = (mode: string, sourceMode: string, unitName: string): GeneralProblem[] => {
  const seeds = SOCIAL_UNIT_SEED_DATA[mode] || [];
  const gradeMatch = mode.match(/^SOCIAL_(\d+)_/);
  const grade = gradeMatch ? Number(gradeMatch[1]) : 7;
  if (grade <= 6) {
    return dedupeByQuestion(seeds);
  }
  const source = SOURCE_MODE_DATA[sourceMode] || [];
  const assignedSlice = getAssignedSourceSlice(mode, sourceMode);
  const keywords = buildKeywords(unitName);
  const assignedRelated = assignedSlice.filter((problem) => isRelated(problem, keywords));
  const relatedOutsideSlice = source.filter(
    (problem) => !assignedSlice.includes(problem) && isRelated(problem, keywords)
  );
  return dedupeByQuestion([
    ...seeds,
    ...assignedRelated,
    ...relatedOutsideSlice,
  ]);
};

const replaceAll = (text: string, replacements: Array<[string, string]>): string =>
  replacements.reduce((result, [from, to]) => result.split(from).join(to), text);

const getGradeFromMode = (mode: string): number => {
  const match = mode.match(/^SOCIAL_(\d+)_/);
  return match ? Number(match[1]) : 7;
};

