const normalizeProblemForMode = (mode: string, problem: GeneralProblem): GeneralProblem => {
  const grade = getGradeFromMode(mode);
  return {
    ...problem,
    question: normalizeTextForGrade(problem.question, grade),
    answer: normalizeTextForGrade(problem.answer, grade),
    options: problem.options.map((option) => normalizeTextForGrade(option, grade)),
    hint: problem.hint ? normalizeTextForGrade(problem.hint, grade) : problem.hint,
  };
};

export const SOCIAL_UNIT_DATA: Record<string, GeneralProblem[]> = Object.fromEntries(
  Object.values(SOCIAL_GRADE_UNITS)
    .flat()
    .map((unit) => [
      unit.mode,
      expandUnitProblems(unit.mode, unit.sourceMode, unit.name).map((problem) =>
        normalizeProblemForMode(unit.mode, problem)
      ),
    ])
);
